"use client";

import { CheckCircle2 } from "lucide-react";
import { useState, type FormEvent } from "react";

import { ImageUploader } from "@/components/ui/image-uploader";
import { Card } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";

type StoryForm = {
  authorName: string;
  authorEmail: string;
  authorUniversity: string;
  authorBatch: string;
  yearOfSelection: string;
  achievement: string;
  quote: string;
  fullStory: string;
  authorPhotoUrl: string;
  authorPhotoPublicId: string;
};

const emptyForm: StoryForm = {
  authorName: "",
  authorEmail: "",
  authorUniversity: "",
  authorBatch: "",
  yearOfSelection: "",
  achievement: "",
  quote: "",
  fullStory: "",
  authorPhotoUrl: "",
  authorPhotoPublicId: "",
};

export function ShareYourStory() {
  const [form, setForm] = useState<StoryForm>(emptyForm);
  const [loading, setLoading] = useState(false);
  const [submitted, setSubmitted] = useState(false);
  const [error, setError] = useState("");

  function update<Key extends keyof StoryForm>(
    key: Key,
    value: StoryForm[Key],
  ) {
    setForm((current) => ({ ...current, [key]: value }));
  }

  function reset() {
    setForm(emptyForm);
    setError("");
    setSubmitted(false);
  }

  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setError("");

    if (
      !form.authorName.trim() ||
      !form.authorEmail.trim() ||
      !form.authorUniversity.trim() ||
      !form.authorBatch.trim() ||
      !form.achievement.trim() ||
      !form.quote.trim()
    ) {
      setError("Complete all required fields before submitting.");
      return;
    }

    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(form.authorEmail.trim())) {
      setError("Enter a valid email address.");
      return;
    }

    if (form.quote.trim().length < 10) {
      setError("Your quote must be at least 10 characters.");
      return;
    }

    setLoading(true);

    const payload = {
      authorName: form.authorName.trim(),
      authorEmail: form.authorEmail.trim(),
      authorUniversity: form.authorUniversity.trim(),
      authorBatch: form.authorBatch.trim(),
      achievement: form.achievement.trim(),
      quote: form.quote.trim(),
      fullStory: form.fullStory.trim() || undefined,
      yearOfSelection: form.yearOfSelection
        ? Number(form.yearOfSelection)
        : undefined,
      authorPhotoUrl: form.authorPhotoUrl || undefined,
      authorPhotoPublicId: form.authorPhotoPublicId || undefined,
    };

    try {
      const response = await fetch("/api/success-stories", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
      });
      const result = (await response.json()) as { error?: string };

      if (response.status !== 201) {
        throw new Error(result.error ?? "Unable to submit your story.");
      }

      setSubmitted(true);
      setForm(emptyForm);
    } catch (caughtError) {
      setError(
        caughtError instanceof Error
          ? caughtError.message
          : "Unable to submit your story. Please try again.",
      );
    } finally {
      setLoading(false);
    }
  }

  return (
    <section className="border-t border-border bg-cream px-6 py-20">
      <div className="mx-auto grid max-w-4xl items-center gap-12 lg:grid-cols-2">
        <div>
          <p className="text-xs font-semibold uppercase tracking-[0.2em] text-accent">
            YOUR STORY
          </p>
          <h2 className="mt-3 font-heading text-3xl font-bold text-primary lg:text-4xl">
            Did you clear the exam? Share your journey.
          </h2>
          <p className="mt-4 max-w-md leading-7 text-muted">
            Your story could be the reason someone else keeps going. Submit it
            and we&apos;ll review it before publishing.
          </p>
          <ul className="mt-6 flex flex-col gap-2 text-sm text-muted">
            <li>Your name and university</li>
            <li>Your batch and year of selection</li>
            <li>A short quote about your preparation</li>
            <li>Optionally, a longer write-up</li>
          </ul>
        </div>

        <Card className="p-6 shadow-sm lg:p-8">
          {submitted ? (
            <div className="py-6 text-center">
              <CheckCircle2
                aria-hidden="true"
                size={42}
                className="mx-auto text-accent"
              />
              <h3 className="mt-4 font-heading text-xl font-semibold text-primary">
                Thank you.
              </h3>
              <p className="mt-2 text-sm leading-6 text-muted">
                Your story has been submitted for review. We&apos;ll publish it
                once approved.
              </p>
              <button
                type="button"
                onClick={reset}
                className="mt-6 cursor-pointer rounded-md border border-border px-4 py-2 text-sm text-primary hover:bg-primary/5"
              >
                Submit another
              </button>
            </div>
          ) : (
            <form onSubmit={submit} className="space-y-4">
              <div>
                <p className="mb-2 text-sm font-medium text-primary">
                  Photo <span className="text-muted">(optional)</span>
                </p>
                <ImageUploader
                  value={form.authorPhotoUrl || null}
                  publicId={form.authorPhotoPublicId || null}
                  onChange={(image) => {
                    update("authorPhotoUrl", image.url ?? "");
                    update("authorPhotoPublicId", image.publicId ?? "");
                  }}
                  folder="bjs-prep/success-stories"
                  aspect="square"
                  size={80}
                />
              </div>

              <div className="grid gap-4 sm:grid-cols-2">
                <Field
                  id="story-author-name"
                  label="Full name"
                  required
                  maxLength={120}
                  value={form.authorName}
                  onChange={(value) => update("authorName", value)}
                />
                <Field
                  id="story-author-email"
                  label="Email"
                  required
                  type="email"
                  autoComplete="email"
                  value={form.authorEmail}
                  onChange={(value) => update("authorEmail", value)}
                />
                <Field
                  id="story-university"
                  label="University"
                  required
                  maxLength={160}
                  value={form.authorUniversity}
                  onChange={(value) => update("authorUniversity", value)}
                />
                <Field
                  id="story-batch"
                  label="Batch"
                  required
                  maxLength={40}
                  placeholder="2019-20"
                  value={form.authorBatch}
                  onChange={(value) => update("authorBatch", value)}
                />
                <Field
                  id="story-selection-year"
                  label="Year of selection"
                  type="number"
                  min={1990}
                  max={2100}
                  value={form.yearOfSelection}
                  onChange={(value) => update("yearOfSelection", value)}
                />
                <Field
                  id="story-achievement"
                  label="Achievement"
                  required
                  maxLength={200}
                  placeholder="Selected as Assistant Judge, 2024"
                  value={form.achievement}
                  onChange={(value) => update("achievement", value)}
                />
              </div>

              <label
                htmlFor="story-quote"
                className="block text-sm font-medium text-primary"
              >
                Short quote
                <Textarea
                  id="story-quote"
                  required
                  rows={3}
                  minLength={10}
                  maxLength={500}
                  value={form.quote}
                  onChange={(event) => update("quote", event.target.value)}
                  className="mt-2"
                />
                <span className="mt-1 block text-right text-xs font-normal text-muted">
                  {form.quote.length} / 500
                </span>
              </label>

              <label
                htmlFor="story-full-story"
                className="block text-sm font-medium text-primary"
              >
                Full story{" "}
                <span className="font-normal text-muted">(optional)</span>
                <Textarea
                  id="story-full-story"
                  rows={8}
                  maxLength={5000}
                  value={form.fullStory}
                  onChange={(event) => update("fullStory", event.target.value)}
                  className="mt-2"
                />
                <span className="mt-1 block text-right text-xs font-normal text-muted">
                  {form.fullStory.length} / 5000
                </span>
              </label>

              {error ? (
                <p role="alert" className="text-sm text-red-600">
                  {error}
                </p>
              ) : null}

              <button
                type="submit"
                disabled={loading}
                className="h-12 w-full cursor-pointer rounded-md bg-primary font-medium text-cream hover:bg-primary-dark disabled:cursor-not-allowed disabled:opacity-60"
              >
                {loading ? "Submitting..." : "Submit story"}
              </button>
            </form>
          )}
        </Card>
      </div>
    </section>
  );
}

function Field({
  id,
  label,
  value,
  onChange,
  ...inputProps
}: {
  id: string;
  label: string;
  value: string;
  onChange: (value: string) => void;
} & Omit<
  React.InputHTMLAttributes<HTMLInputElement>,
  "id" | "value" | "onChange"
>) {
  return (
    <label htmlFor={id} className="block text-sm font-medium text-primary">
      {label}
      <Input
        id={id}
        value={value}
        onChange={(event) => onChange(event.target.value)}
        className="mt-2"
        {...inputProps}
      />
    </label>
  );
}
